 "content": "def transform(grid):
    """Return the pixelwise intersection of the two non-background panels."""
    h, w = len(grid), len(grid[0])

    # The panels are separated by a full-width or full-height solid-color line.
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            a, b = grid[:r], grid[r + 1:]
            if a and b and len(a) == len(b):
                return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                         for j in range(w)] for i in range(len(a))]
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if vals and vals[0] != 0 and all(v == vals[0] for v in vals):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if left and right and len(left[0]) == len(right[0]):
                return [[2 if left[i][j] != 0 and right[i][j] != 0 else 0
                         for j in range(len(left[0]))] for i in range(h)]
    raise ValueError("No solid separator found")
